/*
应用管理 Hook 概述
- 目标：以极简 API 管理应用的插件安装与挂载/卸载流程，屏蔽运行时差异。
- 适配器保障：在缺少 DOMAdapter 时自动注入 BrowserDOMAdapter，确保 DOM 操作能力就绪。
- 组件包装：支持传入组件函数或 {setup, render} 选项对象，统一包装为 FC，以便挂载。
- 容器规范化：支持字符串选择器与元素容器，统一转为 DomElementLike。
- 生命周期：提供 use/mount/unmount 三个方法管理应用，链式调用更便捷。
*/
import type { FC, ComponentInstance, RenderableOutput, Rue } from '../rue'
import { registerRuntimeComponent } from '../component-registry'
import type { DomElementLike } from '../dom'
import { querySelector, settextContent, setAttribute } from '../dom'
import { ensureRuntimeDOMBridge, getClientRuntime, runWithClientRuntime } from '../client-runtime'
import {
  confirmAppContainer,
  releaseAppContainer,
  reserveAppContainer,
  rollbackAppContainer,
} from './app-container-ownership'

/** 创建应用管理器
 * @param AppOrOptions 组件或 {setup, render} 配置
 * @param runtime 可选自定义 Rue 实例
 * @returns 含 use/component/mount/unmount 的应用控制对象
 */
export function useApp(
  AppOrOptions:
    | ComponentInstance
    | {
        /** 应用级 setup，返回值会传给 render。 */
        setup?: () => any
        /** 应用级 render，接收 setup 返回的上下文。 */
        render?: (ctx: any) => RenderableOutput
      },
  runtime?: Rue,
) {
  let containerRef: DomElementLike | null = null
  let pendingContainerRef: DomElementLike | null = null
  const containerOwner = {}
/*
 * [RUE-MOUNT-001] 应用挂载 · 步骤 1：useApp(RootApp)：取得并保存 appRue
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=1
 * 所在阶段：A · 创建时：appRue 和 mount 的来源；节点类型：调用。
 *   1. AppOrOptions 接收 RootApp 函数，因此下面的 App 直接保存这个函数引用；保存引用不会执行 RootApp。
 *   2. 如果传入了自定义 runtime，appRue 就使用它；本例没有传第二个参数，所以执行 getClientRuntime() 取得默认实例。
 *   3. ensureRuntimeDOMBridge(appRue) 确认这个实例已接入当前 DOM 适配器。containerRef、pendingContainerRef 和 containerOwner 则由本次 useApp 单独保存。
 * 执行结果：appRue 被 use、mount、unmount 等方法的闭包持有。useApp 返回的应用管理对象与 appRue 不是同一个对象。
 * 衔接说明：useApp 返回的是应用控制对象；appRue 是它闭包里保存的底层运行时。AppOrOptions 为 RootApp 函数，因此后面 App 就是 RootApp。
 * 断点观察：对比 App === RootApp；观察 appRue 的 mount 属性，以及 useApp 最后 return 出来的对象的 mount 属性。
 */
  const appRue = (runtime as any) || getClientRuntime()
  ensureRuntimeDOMBridge(appRue)

  // 统一包装 App 为 FC
  const App: ComponentInstance =
    typeof AppOrOptions === 'function'
      ? (AppOrOptions as ComponentInstance)
      : (() => {
          const opts = (AppOrOptions || {}) as {
            setup?: () => any
            render?: (ctx: any) => RenderableOutput
          }
          const Wrapper: FC = () => {
            // setup：计算上下文（例如依赖注入、状态初始化）
            const ctx = typeof opts.setup === 'function' ? opts.setup() : {}
            // render：若提供则使用，否则渲染空 div 作为占位
            return typeof opts.render === 'function'
              ? opts.render(ctx)
              : appRue.createElement('div', null, '')
          }
          return Wrapper
        })()

  /** 规范化容器：支持选择器字符串或元素 */
/*
 * [RUE-MOUNT-014] 应用挂载 · 步骤 14：normalizeContainer(container)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=14
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. typeof container === 'string' 成立时，通过导入的 querySelector(container) 查找元素。
 *   2. 找到元素后返回该元素；如果查询没有结果，则通过 || null 返回 null。
 *   3. 如果调用者原本传入的就是元素对象，跳过查询，直接返回这个对象。
 * 执行结果：回到 mount 的 const el = normalizeContainer(container)。本例 el 是真实 #app 元素，container 仍保留原来的字符串。
 * 衔接说明：字符串选择器交给 querySelector(container)，得到真实 DOM 元素 el；如果传入的已经是元素，则直接返回。
 * 断点观察：比较 container 与 el：一个是选择器字符串，一个是元素引用；展开 el 的 nodeType、id。
 */
  const normalizeContainer = (container: string | DomElementLike): DomElementLike | null => {
    if (typeof container === 'string') {
      const el = querySelector(container)
      return (el as DomElementLike) || null
    }
    return container as DomElementLike
  }
  return {
    /** 安装插件到应用，并返回 app 以支持链式调用。 */
/*
 * [RUE-MOUNT-011] 应用挂载 · 步骤 11：useApp() 返回应用控制对象；.use(router) 返回 this
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=11
 * 所在阶段：A · 创建时：appRue 和 mount 的来源；节点类型：调用。
 *   1. use 方法通过闭包取到 appRue，在 runWithClientRuntime 内执行 appRue.use(plugin, ...options)。
 *   2. 这里传入的 plugin 是 router；底层插件管理器接收它，后续挂载时还有 plugins.flush 处理待安装项。
 *   3. return this 返回当前应用管理对象，因此链式调用可以继续访问同一个对象的 mount 方法。
 * 执行结果：表达式接下来调用的是应用管理对象的 mount('#app')，不是直接调用底层 appRue.mount(App, el)。
 * 衔接说明：main.ts 的链式表达式接着调用此应用对象的 mount("#app")。这里的 mount(container) 与 appRue.mount(app, container) 是两个不同方法。
 * 断点观察：在 use 内查看 this、plugin 和 appRue；注意 this 与 appRue 分属两个对象。
 */
    use(plugin: any, ...options: any[]) {
      // 透传到 Rue.use，支持多插件链式安装
      runWithClientRuntime(appRue, () => {
        appRue.use(plugin, ...options)
      })
      return this
    },
    /** 注册运行时组件名，供 <component is="Foo" /> 解析使用。 */
    component(name: string, component: ComponentInstance) {
      registerRuntimeComponent(appRue, name, component)
      return this
    },
    /** 挂载应用到容器，容器可以是选择器字符串或元素对象。 */
/*
 * [RUE-MOUNT-013] 应用挂载 · 步骤 13：useApp 返回对象的 mount(container)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=13
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. container 当前是字符串 '#app'，还不能直接当 DOM 元素操作。
 *   2. App 从闭包读取，本例仍是 RootApp；appRue 也是之前选出的同一个运行时对象。
 *   3. 下一句 normalizeContainer(container) 把字符串或元素两种输入统一成后续能使用的容器。
 * 执行结果：进入容器解析阶段。这里没有再调用 useApp，也没有重新创建 RootApp 函数。
 * 衔接说明：形参 container = "#app"；闭包中 App = RootApp，appRue = 前面保存的 runtime。
 * 断点观察：同时查看参数区的 container 与闭包区的 App、appRue、containerRef。
 */
    mount(container: string | DomElementLike) {
      /*
       * [02 应用挂载]
       * 调用链：main.ts -> useApp.mount() -> runWithClientRuntime() -> appRue.mount()。
       * 观察：container、el、appRue。
       */
      // oxlint-disable-next-line no-debugger -- Rue 源码学习用自动断点。
      if ((globalThis as any).__RUE_RENDER_DEBUG__?.take('02.use-app-mount')) debugger
/*
 * [RUE-MOUNT-015] 应用挂载 · 步骤 15：回到 mount：el 检查、重复挂载检查
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=15
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：返回。
 *   1. 如果 el 为空，if (!el) return 立即结束，不再进入底层 runtime。
 *   2. ownedContainer 优先读取已挂载的 containerRef，否则读取正在挂载的 pendingContainerRef，后者也能挡住挂载中的重复进入。
 *   3. 已经占用同一个 el 时直接返回；已经占用另一个容器时抛错。首次挂载时两者都为空，继续下一步。
 * 执行结果：当前应用自身的检查通过，接着检查这个 el 是否被其他应用占用。
 * 衔接说明：el 为真实 #app；没有元素则结束，同一应用重复挂载同一容器也直接结束。当前首次挂载继续向下。
 * 断点观察：看 el、containerRef、pendingContainerRef 和 ownedContainer，确认走过了哪一个 return 或 throw 条件。
 */
      const el = normalizeContainer(container)
      if (!el) return

      const ownedContainer = containerRef || pendingContainerRef
      if (ownedContainer) {
        if (ownedContainer === el) return
        throw new Error('Rue app is already mounted on a different container.')
      }

/*
 * [RUE-MOUNT-017] 应用挂载 · 步骤 17：回到 mount：保存临时容器与事务标记
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=17
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：返回。
 *   1. 如果 reservation 为空，立即返回；有效 reservation 才能继续。
 *   2. pendingContainerRef = el 表示这个应用正在向该容器挂载，可被前面的重复挂载检查识别。
 *   3. runtimeMountStarted 初始为 false；只有即将进入底层挂载时才设为 true，catch 会据此决定是否尝试底层卸载。
 * 执行结果：后续操作进入 try。此时 containerRef 还没有指向 el，它要等挂载成功后才赋值。
 * 衔接说明：reservation 有效 → pendingContainerRef = el。
 * 断点观察：观察 pendingContainerRef 已有值而 containerRef 仍为空；runtimeMountStarted 仍为 false。
 */
      const reservation = reserveAppContainer(el, containerOwner)
      if (!reservation) return
      pendingContainerRef = el
      let runtimeMountStarted = false

      try {
/*
 * [RUE-MOUNT-018] 应用挂载 · 步骤 18：settextContent(el, "")：先清空根容器
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=18
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. nodeType === 1 说明 el 是元素节点，才执行这段清空逻辑。
 *   2. settextContent(el, '') 通过 DOM 操作层清除元素原有文本与子内容。这里还不是挂载新组件。
 *   3. 辅助函数返回后，继续执行同一个 mount 函数下面的 runtimeMountStarted 和 runWithClientRuntime。
 * 执行结果：容器已清空，但新根组件的 DOM 尚未生成。这条路径是客户端 mount，水合采用现有 SSR DOM 的流程在另一个主题。
 * 衔接说明：首次挂载前先清空 #app 原有内容。此调用结束后继续同一个 mount 函数。
 * 断点观察：观察清空前后的 el.childNodes，以及单步返回后仍位于 useApp.mount 的调用栈。
 */
        if ((el as any).nodeType === 1) {
          // 清空容器文本内容，避免遗留内容干扰渲染
          settextContent(el, '')
        }
        // 执行挂载：将 App 渲染到容器
/*
 * [RUE-MOUNT-019] 应用挂载 · 步骤 19：runWithClientRuntime(appRue, 箭头函数, el)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=19
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：传回调。
 *   1. runtimeMountStarted = true 标记底层挂载即将开始；如果后续抛错，catch 会尝试 appRue.unmount(el)。
 *   2. runWithClientRuntime 接收三个参数：appRue、一个箭头函数、el。箭头函数保存 App、el、appRue，稍后才执行 appRue.mount(App, el)。
 *   3. 为区分同名回调，讲解把这个箭头函数称作 mountRunner；源码没有声明名为 mountRunner 的变量。
 * 执行结果：先进入 runWithClientRuntime 建立活动 runtime 和容器上下文，之后它才会调用刚传入的箭头函数。
 * 衔接说明：第二个参数是 () => { appRue.mount(App, el) }。现在只把函数传进去，尚未执行它。为便于区分，下文称它为 mountRunner；这是说明用名称。
 * 断点观察：进入函数后检查第二个参数 runner，展开函数位置，应指向 useApp.ts 的箭头函数。
 */
        runtimeMountStarted = true
        runWithClientRuntime(
          appRue,
          () => {
             console.trace('11111111111')
/*
 * [RUE-MOUNT-026] 应用挂载 · 步骤 26：回到 useApp.ts：执行 appRue.mount(App, el)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=26
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：执行回调。
 *   1. 读取 appRue 对象的 mount 属性。正常创建路径中，这个属性已被替换为 wrappedRuntimeEntry。
 *   2. 调用时传入 App 和 el，本例对应 RootApp 函数和真实 #app 元素。
 *   3. 采用 appRue.mount(...) 的方法调用形式，因此包装函数收到的 this 是 appRue。
 * 执行结果：下一层进入包装函数，它再转调保存在闭包里的原始 mount。当前回调尚未结束。
 * 衔接说明：实际参数为 [RootApp, el]。从 appRue 对象读取 mount 属性，拿到 wrappedRuntimeEntry。
 * 断点观察：进入 wrappedRuntimeEntry 检查 args[0]、args[1] 和 this，分别对应 RootApp、el、appRue。
 */
            appRue.mount(App, el)
             console.trace('222222222222')
          },
          el,
        )
        // 为容器打标记，便于调试或样式定位
/*
 * [RUE-MOUNT-103] 应用挂载 · 步骤 103：useApp.mount 继续：标记容器、确认归属
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=103
 * 所在阶段：F · 提交 #app → 生命周期 → 逐层返回；节点类型：返回。
 *   1. 如果 el 是元素，写入 data-rue-app 属性，给根容器添加应用标记。
 *   2. 调用 confirmAppContainer(reservation)，验证并确认前面预留的容器凭据。
 *   3. 确认函数成功返回后，containerRef = el 保存正式容器；之后 unmount 会从这里找到要卸载的目标。
 * 执行结果：当前应用正式持有这个容器。pendingContainerRef 还需在最后的 finally 中清除。
 * 衔接说明：runWithClientRuntime 已经全部执行完，才写 data-rue-app、调用 confirmAppContainer 并保存 containerRef = el。
 * 断点观察：观察 el 的 data-rue-app、reservation 和 containerRef；确认赋值发生在底层挂载返回之后。
 */
        if ((el as any).nodeType === 1) setAttribute(el, 'data-rue-app', '')
        confirmAppContainer(reservation)
        containerRef = el
      } catch (error) {
        if (runtimeMountStarted) {
          try {
            runWithClientRuntime(
              appRue,
              () => {
                appRue.unmount(el)
              },
              el,
            )
          } catch {}
        }
        rollbackAppContainer(reservation)
        throw error
      } finally {
/*
 * [RUE-MOUNT-105] 应用挂载 · 步骤 105：useApp.mount finally：清除 pendingContainerRef，返回 main.ts
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=105
 * 所在阶段：F · 提交 #app → 生命周期 → 逐层返回；节点类型：返回。
 *   1. 只有 pendingContainerRef 仍指向本次 el 时才清空它，避免误清其他状态。
 *   2. 成功路径中 containerRef 继续保存 el，容器预留已确认，底层也保留根挂载 record；清空 pending 不会卸载页面。
 *   3. 如果前面发生错误，catch 会按 runtimeMountStarted 尝试底层卸载、回滚 reservation 并重新抛错，最后仍经过这里。
 *   4. 这是应用挂载主题的最后一个节点，后续交给用户交互、路由异步任务或响应式更新重新触发。
 * 执行结果：正常路径返回 main.ts，本行链式挂载调用完成。之后的点击、微任务、路由加载和响应式更新，要从各自触发点另起一条执行链。
 * 衔接说明：本次同步首次挂载结束。后续点击、微任务、懒路由加载另起执行线；不会接在这里冒充当前同步调用。
 * 断点观察：结束时确认 pendingContainerRef 为空、containerRef 为 el、DOM 在 #app 内；不要把后续异步回调排进本次同步返回顺序。
 */
        if (pendingContainerRef === el) pendingContainerRef = null
      }
    },
    /** 从上一次 mount 的容器卸载应用并释放容器引用。 */
    unmount() {
      const mountedContainer = containerRef
      if (mountedContainer) {
        containerRef = null
        try {
          // 执行卸载，释放容器引用
          runWithClientRuntime(
            appRue,
            () => {
              appRue.unmount(mountedContainer)
            },
            mountedContainer,
          )
        } finally {
          releaseAppContainer(mountedContainer, containerOwner)
        }
      }
    },
  }
}
